import subprocess,re
eps=subprocess.run(['git','ls-tree','--name-only','origin/main','S01/'],capture_output=True,text=True).stdout.split()
seen={}
for e in eps:
    txt=subprocess.run(['git','show',f'origin/main:{e}'],capture_output=True,text=True).stdout
    shas=re.findall(r'Source: (friend/\w+) @ ([0-9a-f]{40})',txt)
    for br,sha in shas:
        seen.setdefault(sha,[]).append((e,br))
    dupes=[s for s in shas if shas.count(s)>1]
    print(f"{e}: {len(shas)} entries, dupes={len(set(dupes))}")
cross={s:v for s,v in seen.items() if len({v2[0] for v2 in v})>1}
print("SHAs appearing in multiple episodes:",len(cross))
for s,v in list(cross.items())[:5]: print("  ",s[:10],v)
EOF
